function adapt(input, solve, kit) {
  // LeetCode's N-ary node: a value and an ordered array of children.
  class Node {
    constructor(val = 0, children = []) {
      this.val = val;
      this.children = children;
    }
  }
  globalThis.Node = Node;
  globalThis._Node = Node;
  const values = input[1][1][0];
  const original = [];
  let root = null;
  if (values.length) {
    root = new Node(values[0], []);
    original.push(root);
    let index = 2;
    for (let head = 0; head < original.length && index < values.length; head++) {
      while (index < values.length && values[index] !== null) {
        const child = new Node(values[index], []);
        original[head].children.push(child);
        original.push(child);
        index++;
      }
      index++;
    }
  }
  const data = new solve().serialize(root);
  if (typeof data !== 'string') throw new Error('serialize must return a string.');
  const rebuilt = new solve().deserialize(data);
  if (rebuilt === undefined) throw new Error('deserialize did not return a value.');
  if (rebuilt === null) return [];
  // Write the rebuilt tree in LeetCode's level order, checking that it is a fresh, finite tree.
  const used = new Set(original);
  const seen = new Set();
  const out = [rebuilt.val, null];
  const queue = [rebuilt];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    if (!node || typeof node !== 'object') throw new Error('Every child must be a node object.');
    if (used.has(node)) throw new Error('deserialize must build new nodes from the string, not return the original tree.');
    if (seen.has(node) || queue.length > values.length + 2000) throw new Error('The rebuilt tree contains a cycle, a shared node, or too many nodes.');
    seen.add(node);
    const children = node.children == null ? [] : node.children;
    if (!Array.isArray(children)) throw new Error('children must be an array of nodes.');
    for (const child of children) {
      if (!child || typeof child !== 'object') throw new Error('Every child must be a node object.');
      out.push(child.val === undefined ? null : child.val);
      queue.push(child);
    }
    out.push(null);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return out;
}

