class Codec {
  // LeetCode's own breadth-first format: each node's children, closed by '#'.
  serialize(root) {
    if (!root) return '';
    const tokens = [String(root.val), '#'];
    const queue = [root];
    for (let head = 0; head < queue.length; head++) {
      for (const child of queue[head].children) {
        tokens.push(String(child.val));
        queue.push(child);
      }
      tokens.push('#');
    }
    return tokens.join(' ');
  }

  deserialize(data) {
    if (!data) return null;
    const tokens = data.split(' ');
    const root = new Node(Number(tokens[0]), []);
    const queue = [root];
    let position = 2;
    for (let head = 0; head < queue.length; head++) {
      while (tokens[position] !== '#') {
        const child = new Node(Number(tokens[position]), []);
        queue[head].children.push(child);
        queue.push(child);
        position++;
      }
      position++;
    }
    return root;
  }
}

