function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 850 + pick(100) : pick(13);
  if (n === 0) return [["Codec", "serialize"], [[], [[]]]];
  const maxValue = large || rand() < 0.5 ? 10000 : 4;
  const values = Array.from({ length: n }, () => pick(maxValue + 1));
  // style 0 attaches anywhere, 1 grows deep and thin, 2 hangs many children on a few nodes.
  const style = pick(3);
  const parents = [-1];
  for (let i = 1; i < n; i++) {
    if (style === 0) parents.push(pick(i));
    else if (style === 1) parents.push(Math.max(0, i - 1 - pick(2)));
    else parents.push(pick(Math.min(i, 3)));
  }
  const children = values.map(() => []);
  for (let i = 1; i < n; i++) children[parents[i]].push(i);
  const root = [values[0], null];
  const queue = [0];
  for (let head = 0; head < queue.length; head++) {
    for (const child of children[queue[head]]) {
      root.push(values[child]);
      queue.push(child);
    }
    root.push(null);
  }
  while (root[root.length - 1] === null) root.pop();
  return [["Codec", "serialize"], [[], [root]]];
}
